std::lock_guard<std::mutex> lock(lfs->mutex);
lfs_block_t best_block = LFS_BLOCK_NONE;
uint32_t min_erase_count = std::numeric_limits<uint32_t>::max();
uint32_t lookahead_start = lfs->lookahead_pos;
uint32_t lookahead_end = lookahead_start + LFS_LOOKAHEAD_SIZE;
lookahead_end = lookahead_end > lfs->block_count ? lfs->block_count : lookahead_end;

for (uint32_t i = lookahead_start; i < lookahead_end; i++) {
    if (lfs->block_state[i] == LFS_BLOCK_FREE) {
        if (lfs->erase_count[i] < min_erase_count) {
            min_erase_count = lfs->erase_count[i];
            best_block = i;
        }
    }
}

if (best_block == LFS_BLOCK_NONE) {
    // Wrap around if no block found in lookahead window
    for (uint32_t i = 0; i < lookahead_start; i++) {
        if (lfs->block_state[i] == LFS_BLOCK_FREE) {
            if (lfs->erase_count[i] < min_erase_count) {
                min_erase_count = lfs->erase_count[i];
                best_block = i;
            }
        }
    }
}

if (best_block == LFS_BLOCK_NONE) {
    return LFS_ERR_NOSPC;
}

lfs->block_state[best_block] = LFS_BLOCK_ALLOCATED;
lfs->erase_count[best_block]++;
*block = best_block;
lfs->lookahead_pos = (lookahead_start + 1) % lfs->block_count;
return 0;
// END_CODE

